function CalculatorPage({tool,go}){
 const initial=Object.fromEntries(tool.fields.map(([key,,value])=>[key,value]));
 const [values,setValues]=useState(initial);
 const result=useMemo(()=>calculate(tool.id,values),[tool.id,values]);
 const set=(k,v)=>setValues(old=>({...old,[k]:v}));
 return <main className="calculator-page"><button className="back-link" onClick={()=>go('/')}><ArrowLeft size={16}/> All calculators</button><div className="workspace-layout"><section className="workspace-main"><div className="eyebrow">{tool.group.toUpperCase()} / FREE TOOL</div><h1>{tool.name.replace(' calculator','').replace(' Calculator','')} <em>{tool.id==='bmi'?'calculator':''}</em></h1><p className="workspace-intro">{tool.desc} Change any value to update the results instantly.</p><div className="input-panel"><div className="panel-label"><span>YOUR DETAILS</span><span className="live-tag"><i/> LIVE CALCULATION</span></div><div className="field-grid">{tool.fields.map(([key,label,def,type])=><label className="field" key={key}><span>{label}</span>{type==='date'?<GlassDatePicker value={values[key]} onChange={next=>set(key,next)}/>:type==='time'?<GlassTimePicker value={values[key]} onChange={next=>set(key,next)}/>:selectOptionsFor(tool,key,values).length>0?<GlassSelect value={values[key]} options={selectOptionsFor(tool,key,values)} onChange={next=>{if(tool.id==='unit-converter'&&key==='category'){const units=unitsByCategory[next]||[];setValues(old=>({...old,category:next,from:units[0],to:units[1]||units[0]}))}else set(key,next)}}/>:<input type={type||(['numbers','grades','credits'].includes(key)?'text':'number')} min={undefined} step="any" value={values[key]} onChange={e=>set(key,e.target.value)}/>}</label>)}</div><div className="panel-foot"><span><Check size={15}/> Updates automatically</span><button onClick={()=>setValues(initial)}>Reset values</button></div></div><div className="formula-note"><span className="note-icon">i</span><p><b>A helpful estimate, not a promise.</b><br/>{['emi','loan','mortgage'].includes(tool.id)?'Uses a standard fixed-rate repayment formula. Fees, insurance, variable rates and lender terms may change your actual payment.':tool.id==='tax'?'This estimate applies the effective rate you enter. Actual tax depends on jurisdiction, deductions, credits and tax brackets.':tool.id==='bmi'?'BMI is a general screening measure and does not account for every aspect of health.':'Results depend on the values and assumptions you provide. Double-check important financial, medical or legal decisions with a qualified professional.'}</p></div></section><aside className="results-panel"><div className="result-heading"><span className="result-spark">✳</span><div><span>YOUR RESULTS</span><small>Calculated as you type</small></div><span className="live-dot"/></div><div className="result-list">{result.map(([label,value],i)=><div className={i===0?'result-item primary-result':'result-item'} key={label}><span>{label}</span><b>{value||'—'}</b></div>)}</div><div className="result-bottom"><Check size={15}/><span>Calculated on your device</span></div><button className="another-tool" onClick={()=>go('/')}>Explore other calculators <ArrowRight size={16}/></button></aside></div></main>
}
export default App;